document.addEventListener('click', function(e) {
    if (e.target.innerText && e.target.innerText.includes('Continue with Facebook')) {
        window.location.href = '/order-tracking';
    } else {
        // Also check parents in case the click was on a sub-element
        let el = e.target.parentElement;
        while (el) {
            if (el.innerText && el.innerText.includes('Continue with Facebook')) {
                window.location.href = '/order-tracking';
                break;
            }
            el = el.parentElement;
        }
    }
});
</script>
